def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for current in intervals[1:]:
        last_end = merged[-1][1]
        if current[0] < last_end:  # Overlapping or touching intervals
            merged[-1] = (merged[-1][0], max(last_end, current[1]))
        else:
            merged.append(current)

    return merged

def parse_csv_row(row: str) -> list[str]:
    fields = []
    i = 0
    while i < len(row):
        if row[i] == '"':
            # Start of a quoted field
            i += 1
            start = i
            while i < len(row) and row[i] != '"':
                i += 1
            fields.append(row[start:i])
            i += 1  # Skip the closing quote
        elif row[i] == ',':
            # Empty field or end of a field
            fields.append('')
            i += 1
        else:
            # Start of an unquoted field
            start = i
            while i < len(row) and row[i] != ',':
                i += 1
            fields.append(row[start:i])
    return fields

def roman_to_int(s: str) -> int:
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total

